    totalReviewed: data.totalReviewed || 6,
    validCount: data.validCount || 1,
    invalidCount: data.invalidCount || 5,
    warnings: []
  },
  timestamp: new Date().toISOString()
};

console.log(JSON.stringify(payload, null, 2));
